package com.pharmapack.qms.reconciliation; import com.pharmapack.qms.batch.Batch; import jakarta.persistence.*; import lombok.*; import java.math.*; import java.time.*;
@Entity @Table(name="reconciliations") @Getter @Setter @NoArgsConstructor public class Reconciliation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="batch_id",unique=true) Batch batch; BigDecimal startingQuantity=BigDecimal.ZERO,goodQuantity=BigDecimal.ZERO,rejectQuantity=BigDecimal.ZERO,unusedQuantity=BigDecimal.ZERO,reconciledQuantity=BigDecimal.ZERO,variance=BigDecimal.ZERO; String status="INVESTIGATION_REQUIRED"; LocalDateTime calculatedAt; Long calculatedBy; String remarks; }
